begin;
select set_config('qa.store','qa-push-'||gen_random_uuid()::text,true),set_config('qa.other_store','qa-push-'||gen_random_uuid()::text,true),set_config('qa.manager',gen_random_uuid()::text,true),set_config('qa.worker',gen_random_uuid()::text,true),set_config('qa.other',gen_random_uuid()::text,true),set_config('qa.device',gen_random_uuid()::text,true);
insert into public.stores(id,name,address) values(current_setting('qa.store'),'Запросы: тест','Учебный'),(current_setting('qa.other_store'),'Другой магазин: тест','Учебный');
insert into auth.users(id,email) select current_setting(k)::uuid,current_setting(k)||'@example.invalid' from unnest(array['qa.manager','qa.worker','qa.other']) k;
insert into public.users(id,name,role,store_id) values(current_setting('qa.manager')::uuid,'Тест управляющего','manager',current_setting('qa.store')),(current_setting('qa.worker')::uuid,'Тест сотрудника','rtz',current_setting('qa.store')),(current_setting('qa.other')::uuid,'Чужой сотрудник','srtz',current_setting('qa.other_store'));
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('qa.worker'),true);
do $$begin
 if has_function_privilege('authenticated','public.manager_request_staff_push(uuid,uuid)','execute') or has_function_privilege('anon','public.get_staff_push_request(uuid)','execute') then raise exception 'internal API exposed';end if;
 begin perform id from public.staff_push_enable_requests;raise exception 'request table exposed';exception when insufficient_privilege then null;end;
end $$;
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role service_role;
do $$declare r jsonb; first_id uuid;new_id uuid;due timestamptz;created timestamptz;begin
 begin perform public.manager_request_staff_push(current_setting('qa.worker')::uuid,current_setting('qa.other')::uuid);raise exception 'staff requested';exception when insufficient_privilege then null;end;
 begin perform public.manager_request_staff_push(current_setting('qa.manager')::uuid,current_setting('qa.other')::uuid);raise exception 'foreign store requested';exception when insufficient_privilege then null;end;
 begin perform public.manager_request_staff_push(current_setting('qa.manager')::uuid,current_setting('qa.manager')::uuid);raise exception 'manager self request';exception when insufficient_privilege then null;end;
 r:=public.manager_request_staff_push(current_setting('qa.manager')::uuid,current_setting('qa.worker')::uuid);
 if r->>'status'<>'pending' then raise exception 'request not stored';end if;
 created:=(r->>'requested_at')::timestamptz;
 r:=public.get_staff_push_request(current_setting('qa.worker')::uuid);first_id:=(r->>'id')::uuid;
 if first_id is null or r->>'manager_name'<>'Тест управляющего' then raise exception 'request not shown';end if;
 if public.get_staff_push_request(current_setting('qa.other')::uuid) is not null then raise exception 'foreign user sees request';end if;
 if public.snooze_staff_push_request(current_setting('qa.other')::uuid,first_id)->>'status'<>'inactive' then raise exception 'foreign snooze';end if;
 r:=public.snooze_staff_push_request(current_setting('qa.worker')::uuid,first_id);due:=(r->>'until')::timestamptz;
 if r->>'status'<>'snoozed' or (due at time zone 'Europe/Moscow')::date<>(now() at time zone 'Europe/Moscow')::date+1 or (due at time zone 'Europe/Moscow')::time<>'00:00'::time then raise exception 'wrong next day';end if;
 if public.get_staff_push_request(current_setting('qa.worker')::uuid) is not null then raise exception 'snooze ignored';end if;
 r:=public.manager_request_staff_push(current_setting('qa.manager')::uuid,current_setting('qa.worker')::uuid);
 if (r->>'requested_at')::timestamptz<>created or (select snoozed_until from public.staff_push_enable_requests where id=first_id)<>due then raise exception 'repeat reset snooze';end if;
 if jsonb_array_length(public.manager_staff_push_requests(current_setting('qa.manager')::uuid))<>1 then raise exception 'pending missing';end if;
 update public.staff_push_enable_requests set snoozed_until=now()-interval '1 minute' where id=first_id;
 if public.get_staff_push_request(current_setting('qa.worker')::uuid) is null then raise exception 'next day not shown';end if;
 insert into public.push_subscriptions(id,user_id,endpoint,keys) values(current_setting('qa.device')::uuid,current_setting('qa.worker')::uuid,'https://fcm.googleapis.com/fcm/send/qa-not-a-device','{"p256dh":"fake","auth":"fake"}');
 if public.get_staff_push_request(current_setting('qa.worker')::uuid) is not null or (select resolved_at from public.staff_push_enable_requests where id=first_id) is null then raise exception 'subscribe did not resolve';end if;
 if public.manager_request_staff_push(current_setting('qa.manager')::uuid,current_setting('qa.worker')::uuid)->>'status'<>'already-enabled' then raise exception 'enabled user requested';end if;
 delete from public.push_subscriptions where id=current_setting('qa.device')::uuid;
 perform public.manager_request_staff_push(current_setting('qa.manager')::uuid,current_setting('qa.worker')::uuid);
 new_id:=(public.get_staff_push_request(current_setting('qa.worker')::uuid)->>'id')::uuid;
 if new_id=first_id or new_id is null then raise exception 'new request did not renew id';end if;
 if public.snooze_staff_push_request(current_setting('qa.worker')::uuid,first_id)->>'status'<>'inactive' then raise exception 'old request changed new one';end if;
end $$;
reset role;
update public.users set store_id=current_setting('qa.other_store') where id=current_setting('qa.worker')::uuid;
do $$begin if exists(select 1 from public.staff_push_enable_requests where user_id=current_setting('qa.worker')::uuid and resolved_at is null) then raise exception 'transfer did not cancel';end if;end $$;
update public.users set store_id=current_setting('qa.store') where id=current_setting('qa.worker')::uuid;
set local role service_role;
select public.manager_request_staff_push(current_setting('qa.manager')::uuid,current_setting('qa.worker')::uuid);
reset role;
update public.users set role='rtz' where id=current_setting('qa.manager')::uuid;
do $$begin if exists(select 1 from public.staff_push_enable_requests where requested_by=current_setting('qa.manager')::uuid and resolved_at is null) then raise exception 'manager demotion did not cancel';end if;end $$;
select 'PASS: manager scope, ownership, no exposed internal API, idempotent request, daily snooze, subscribe resolution, stale request and role/store invalidation' as result;
rollback;
